// Prints the level solutions as Markdown. `npm run solutions` saves the output
// to docs/solutions.local.md, which is git-ignored and never part of the
// built game, so solutions are not committed or published.

import type { CellType } from "../src/game/types";
import { analyzeLevels, rowList } from "./levelAnalysis";

const SYMBOLS: Record<CellType, string> = {
  empty: ".",
  mirrorBackslash: "\\",
  mirrorSlash: "/",
  wall: "#",
  goal: "G",
};

const analyses = analyzeLevels();
const lines: string[] = [
  "# Level solutions",
  "",
  "Generated by `npm run solutions` (also run by `npm run build`) from",
  "`src/levels/levels.ts`. Do not edit: changes are overwritten. Not committed",
  "and not published. Rows are numbered from 1 at the top.",
  "",
  "| # | Level | Par | Solution (rows) | Two-shot setup routes |",
  "|---|---|---|---|---|",
];

for (const { number, level, solution, setupRoutes } of analyses) {
  const routes =
    setupRoutes.length > 0 ? setupRoutes.map(rowList).join(", ") : "–";
  lines.push(
    `| ${number} | ${level.name} | ${level.minShots} | ${solution ? rowList(solution) : "none found"} | ${routes} |`,
  );
}

for (const analysis of analyses) {
  const { number, level, board, solutionShots, setupRoutes } = analysis;
  lines.push("", `## ${number}. ${level.name}`, "");
  lines.push(
    `Par ${level.minShots}` +
      ((level.goalHits ?? 1) > 1
        ? ` · goal needs ${level.goalHits} hits`
        : "") +
      ` · ${board.width}×${board.height} · id \`${level.id}\`` +
      (analysis.minShotsConfirmed
        ? ""
        : ` · **solver disagrees with minShots ${level.minShots}**`),
  );

  lines.push("", "```");
  lines.push(
    `     ${Array.from({ length: board.width }, (_, x) => x + 1).join(" ")}`,
  );
  board.cells.forEach((row, y) => {
    const cells = row.map((cell) => SYMBOLS[cell]).join(" ");
    lines.push(`${String(y + 1).padStart(3)}  ${cells}`);
  });
  lines.push("```", "");

  solutionShots.forEach(({ row, outcome, flips }, index) => {
    const flipped = flips === 1 ? "1 mirror" : `${flips} mirrors`;
    lines.push(
      `${index + 1}. Row ${row + 1}: ${outcome === "goal" ? "**goal**" : outcome}, flips ${flipped}`,
    );
  });
  if (setupRoutes.length > 0 && level.minShots === 1) {
    lines.push(
      "",
      `Also solvable with a setup shot: ${setupRoutes.map(rowList).join(", ")}.`,
    );
  }
}

console.log(lines.join("\n"));
